CREATE FUNCTION public.save_gym_records(g uuid, changes jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c jsonb; r jsonb; k text; a text; rid text; cid uuid; old jsonb; ids text[]; BEGIN IF jsonb_typeof(changes)!='array' OR jsonb_array_length(changes)>12 THEN RAISE EXCEPTION 'Invalid changes'; END IF; PERFORM pg_advisory_xact_lock(hashtext(g::text)); FOR c IN SELECT * FROM jsonb_array_elements(changes) LOOP k=c->>'kind'; a=CASE k WHEN 'gym' THEN 'Settings' WHEN 'members' THEN 'Members' WHEN 'plans' THEN 'Members' WHEN 'workouts' THEN 'Workout programs' WHEN 'trainers' THEN 'Workout programs' WHEN 'sessions' THEN 'Sessions' WHEN 'attendance' THEN 'Attendance' WHEN 'staffAttendance' THEN 'Attendance' WHEN 'products' THEN 'Finance' WHEN 'recurring' THEN 'Finance' WHEN 'transactions' THEN 'Finance' ELSE NULL END; IF a IS NULL OR NOT public.gym_access(g,a) THEN RAISE EXCEPTION 'Not authorized'; END IF; ids=ARRAY[]::text[]; FOR r IN SELECT * FROM jsonb_array_elements(c->'rows') LOOP rid=r->>'id'; IF rid IS NULL OR length(rid)>100 OR pg_column_size(r)>1048576 THEN RAISE EXCEPTION 'Invalid record'; END IF; ids=array_append(ids,rid); cid=NULL; IF k='members' THEN IF r->>'expiry'<r->>'start' OR (r->>'sessionsLeft')::int<0 THEN RAISE EXCEPTION 'Invalid membership'; END IF; IF coalesce(r->>'clientId','')!='' THEN cid=(r->>'clientId')::uuid; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=cid) THEN RAISE EXCEPTION 'Client not found'; END IF; IF EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind='members' AND client_id=cid AND id!=rid) THEN RAISE EXCEPTION 'Client already belongs to this gym'; END IF; END IF; SELECT data INTO old FROM public.gym_records WHERE gym_id=g AND kind=k AND id=rid; IF old IS NOT NULL THEN r=r||jsonb_build_object('planPrice',old->'planPrice','createdByName',old->'createdByName'); ELSE r=r||jsonb_build_object('createdByName',(SELECT full_name FROM public.profiles WHERE id=auth.uid()),'planPrice',coalesce((SELECT data->'price' FROM public.gym_records WHERE gym_id=g AND kind='plans' AND data->>'name'=r->>'plan' LIMIT 1),'0'::jsonb)); END IF; END IF; IF k IN ('attendance','staffAttendance') THEN IF NOT EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind=k AND id=rid) AND EXISTS(SELECT 1 FROM public.gym_records WHERE gym_id=g AND kind=k AND data->>'date'=r->>'date' AND coalesce(data->>'staffId',data->>'memberId',data->>'name')=coalesce(r->>'staffId',r->>'memberId',r->>'name')) THEN RAISE EXCEPTION 'Already checked in on this date'; END IF; IF k='attendance' THEN SELECT client_id INTO cid FROM public.gym_records WHERE gym_id=g AND kind='members' AND id=r->>'memberId'; END IF; IF k='staffAttendance' AND coalesce(r->>'staffId','')!='' AND NOT EXISTS(SELECT 1 FROM public.user_roles WHERE gym_id=g AND user_id=(r->>'staffId')::uuid AND role!='Client') THEN RAISE EXCEPTION 'Staff member does not belong to this gym'; END IF; END IF; INSERT INTO public.gym_records(gym_id,kind,id,data,client_id,created_by) VALUES(g,k,rid,r,cid,auth.uid()) ON CONFLICT(gym_id,kind,id) DO UPDATE SET data=excluded.data,client_id=excluded.client_id; END LOOP; DELETE FROM public.gym_records WHERE gym_id=g AND kind=k AND NOT(id=ANY(ids)); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.save_gym_records(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.save_gym_records(uuid,jsonb) TO authenticated;
CREATE FUNCTION public.client_gym_link() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF new.kind='members' AND new.client_id IS NOT NULL THEN INSERT INTO public.user_roles(user_id,gym_id,role) VALUES(new.client_id,new.gym_id,'Client') ON CONFLICT(user_id,gym_id) DO NOTHING; END IF; RETURN new; END $$;
CREATE TRIGGER gym_member_link AFTER INSERT OR UPDATE ON public.gym_records FOR EACH ROW EXECUTE FUNCTION public.client_gym_link();